```cpp
#include <string>
#include <regex>

std::string markdownToHtml(std::string& markdown) {
    // Convert headers
    std::regex headerRegex("^# (.*)");
    markdown = std::regex_replace(markdown, headerRegex, "<h1>\\1</h1>");

    // Convert bold text
    std::regex boldRegex("\\*\\*(.*?)\\*\\*");
    markdown = std::regex_replace(markdown, boldRegex, "<b>\\1</b>");

    // Convert italic text
    std::regex italicRegex("\\*(.*?)\\*");
    markdown = std::regex_replace(markdown, italicRegex, "<i>\\1</i>");

    return markdown;
}
```

### Usage Example:
```cpp
#include <iostream>

int main() {
    std::string markdown = "# Header\n**Bold** text and *italic* text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

